package shop.ultimatesmp.crates;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer;
class CrateFeaturesTest {
 private Crate.Reward reward(LootPolicy.Rarity rarity){return new Crate.Reward(CratesTest.item(Material.DIAMOND,1,"reward"),1,rarity,null);}
 @Test void groupBudgetsSplitAmongItems(){var r=List.of(reward(LootPolicy.Rarity.COMMON),reward(LootPolicy.Rarity.COMMON),reward(LootPolicy.Rarity.UNCOMMON),reward(LootPolicy.Rarity.RARE),reward(LootPolicy.Rarity.LEGENDARY));assertArrayEquals(new double[]{.30,.30,.25,.12,.03},LootPolicy.chances(r),1e-10);}
 @Test void missingRaritiesRebalanceAndLegacyWeightsRemain(){assertArrayEquals(new double[]{.5,.5},LootPolicy.chances(List.of(reward(LootPolicy.Rarity.COMMON),reward(LootPolicy.Rarity.COMMON))),1e-10);var item=CratesTest.item(Material.DIAMOND,1,"reward");assertArrayEquals(new double[]{.25,.75},LootPolicy.chances(List.of(new Crate.Reward(item,1),new Crate.Reward(item,3))),1e-10);}
 @Test void manualOverrideLeavesRestToPresetGroups(){var fixed=new Crate.Reward(CratesTest.item(Material.DIAMOND,1,"a"),1,LootPolicy.Rarity.LEGENDARY,10d);assertArrayEquals(new double[]{.1,.9},LootPolicy.chances(List.of(fixed,reward(LootPolicy.Rarity.COMMON))),1e-10);assertThrows(IllegalArgumentException.class,()->LootPolicy.chances(List.of(fixed)));assertThrows(IllegalArgumentException.class,()->LootPolicy.chances(List.of(new Crate.Reward(fixed.item(),1,LootPolicy.Rarity.COMMON,70d),new Crate.Reward(fixed.item(),1,LootPolicy.Rarity.RARE,40d))));}
 @Test void weightedSamplingAndZeroChanceBoundaries(){var item=CratesTest.item(Material.DIAMOND,1,"a");var r=List.of(new Crate.Reward(item,1,LootPolicy.Rarity.COMMON,0d),new Crate.Reward(item,1,LootPolicy.Rarity.RARE,25d),new Crate.Reward(item,1,LootPolicy.Rarity.LEGENDARY,75d));assertEquals(1,LootPolicy.choose(r,0));assertEquals(2,LootPolicy.choose(r,.25));assertEquals(2,LootPolicy.choose(r,.999999));assertThrows(IllegalArgumentException.class,()->LootPolicy.choose(r,Double.NaN));}
 @Test void labelBoundsFormattingAndLegacyPayload()throws Exception{var style=LabelStyle.defaults().color("#ff00aa").size(2).text("{name}\\n&bKeys");assertEquals("Rare\nKeys",PlainTextComponentSerializer.plainText().serialize(style.component("Rare")));assertThrows(IllegalArgumentException.class,()->style.size(Float.NaN));assertThrows(IllegalArgumentException.class,()->style.height(Double.POSITIVE_INFINITY));assertThrows(IllegalArgumentException.class,()->style.color("invalid"));Crate legacy=CrateCodec.decode("id: common\nname: Common\nrevision: 1\n");assertEquals(LabelStyle.defaults(),legacy.label());Crate round=CrateCodec.decode(CrateCodec.encode(new Crate("common","Common",2,List.of(),style)));assertEquals(style,round.label());}
 @Test void keyAllDoesNotLoseKeysOrModifySkippedInventories(){Player good=mock(Player.class),full=mock(Player.class),loading=mock(Player.class);PlayerInventory one=mock(PlayerInventory.class),two=mock(PlayerInventory.class);when(good.getInventory()).thenReturn(one);when(full.getInventory()).thenReturn(two);when(one.getStorageContents()).thenReturn(new ItemStack[]{null});var stone=CratesTest.item(Material.STONE,64,"stone");when(two.getStorageContents()).thenReturn(new ItemStack[]{stone});var keys=CratesTest.item(Material.TRIPWIRE_HOOK,5,"key");var result=KeyDistributor.give(List.of(good,full,loading),keys,p->p!=loading);assertEquals(new KeyDistributor.Result(1,1,1),result);verify(one).setStorageContents(any());verify(two,never()).setStorageContents(any());verify(loading,never()).getInventory();assertEquals(64,stone.getAmount());assertEquals(5,keys.getAmount());}
 @Test void negativeChunkCoordinatesUseFloorShift(){var p=CrateLabels.Position.parse("ultimate_spawn:-1:-56:-17");assertEquals(-1,p.x()>>4);assertEquals(-2,p.z()>>4);}
}

